#!/usr/bin/env python
"""差异集 14 门禁：发行版附加第三方组件声明（含 tgz 分层预置的组件）。

背景：上游 `THIRD_PARTY_NOTICES.md` 由 `scripts/gen-third-party-notices.ts` 生成（文件头写明
*do not edit by hand*，且有 spec 断言提交字节与生成结果一致），而其生成器只扫描**上游 pnpm
workspace 的 package.json** —— 本发行版以 tgz 分层预置的组件（`dshmarket` 等）不在其中。
因此按 `WORKNEXUS-RELEASE-NOTES.md` 的既有处置，新增**发行版附加声明**并随包落盘。

断言：
  P1  输入齐备：锁文件 / 许可证原文 / 生成器脚本
  P2  上游声明文件与生成器输出**逐字节一致**（防手工漂移）
  P3  随包落点：electron-builder 配置把该文件放进安装目录
  P4  覆盖性：锁文件里每个组件都以 `name` + `version` + `license` + 许可证原文首行出现在声明中
  P5  负向：未改动上游生成的 `THIRD_PARTY_NOTICES.md`（两者文件不同、内容不互相覆盖）
P6  差异集 14 补丁 = 1 个新增上游文件；上游差异集条目数 = 120
  P7  安装态（存在安装时）：`resources/WORKNEXUS-THIRD-PARTY-NOTICES.md` 落盘且含全部组件

用法：python scripts/verify_diffset14_third_party_notices.py
退出码：全部通过为 0；任一 [FAIL] 为 1。
"""

from __future__ import annotations

import json
import os
import re
import subprocess
import sys
from pathlib import Path

if hasattr(sys.stdout, "reconfigure"):
    sys.stdout.reconfigure(encoding="utf-8")

REPO = Path(__file__).resolve().parent.parent
UPSTREAM = REPO / "repos" / "deepseek-harness"
LOCK = REPO / "configs" / "vendor" / "third-party-bundles.lock.json"
LICENSES = REPO / "configs" / "vendor" / "licenses"
GENERATOR = REPO / "scripts" / "gen_worknexus_notices.py"
DECLARATION = UPSTREAM / "WORKNEXUS-THIRD-PARTY-NOTICES.md"
UPSTREAM_NOTICES = UPSTREAM / "THIRD_PARTY_NOTICES.md"
BUILDER_CONFIG = UPSTREAM / "apps" / "desktop" / "scripts" / "electron-builder-config.mjs"
PATCH_14 = REPO / "patches" / "diffset-14-third-party-notices.patch"
NEW_FILE = "WORKNEXUS-THIRD-PARTY-NOTICES.md"
EXPECTED_DIFFSET_PATHS = 120
INSTALL = Path(os.environ.get("LOCALAPPDATA", "")) / "Programs" / "WorkNexus-DSH"


def license_stem(name: str, version: str) -> str:
    """许可证原文的落盘名（scoped 包的 `/` 换成 `-`，与取回脚本/生成器一致）。"""
    return f"{name.replace('/', '-')}-{version}"


RESULTS: list[tuple[bool, str]] = []


def record(ok: bool, detail: str) -> None:
    RESULTS.append((ok, detail))
    print(f"[{'OK' if ok else 'FAIL'}] {detail}")


def read(path: Path) -> str:
    return path.read_text(encoding="utf-8", errors="replace") if path.exists() else ""


def git(*args: str) -> str:
    proc = subprocess.run(["git", *args], cwd=str(UPSTREAM), capture_output=True,
                          text=True, encoding="utf-8", errors="replace", check=False)
    return proc.stdout if proc.returncode == 0 else ""


def main() -> int:
    print("=" * 60)
    print("差异集 14 门禁：发行版附加第三方组件声明")
    print("=" * 60)

    lock = json.loads(LOCK.read_text(encoding="utf-8")) if LOCK.is_file() else {"packages": []}
    packages = lock["packages"]

    # ── P1 输入齐备 ──
    missing = [str(p.relative_to(REPO)) for p in
               [LOCK, GENERATOR, *[LICENSES / f"{license_stem(e['name'], e['version'])}.LICENSE.txt"
                                   for e in packages]]
               if not p.is_file()]
    record(not missing, f"P1 生成输入齐备（缺: {missing or '无'}）")

    # ── P2 与生成结果逐字节一致 ──
    check = subprocess.run([sys.executable, str(GENERATOR), "--check"], cwd=str(REPO),
                           capture_output=True, text=True, encoding="utf-8", errors="replace", check=False)
    record(check.returncode == 0,
           f"P2 声明文件与生成器输出逐字节一致（{(check.stdout or check.stderr).strip()[:160]}）")

    # ── P3 随包落点 ──
    config_text = read(BUILDER_CONFIG)
    record(NEW_FILE in config_text and "extraResources" in config_text,
           "P3 electron-builder extraResources 引用发行版附加声明")

    # ── P4 覆盖性 ──
    declaration = read(DECLARATION)
    gaps: list[str] = []
    for entry in packages:
        for token in (f"`{entry['name']}`", entry["version"], entry["license"]):
            if token not in declaration:
                gaps.append(f"{entry['name']}@{entry['version']}:{token}")
    record(not gaps, f"P4 锁文件每个组件都登记（缺: {gaps or '无'}）")

    # ── P5 负向：未手改上游生成物 ──
    upstream_text = read(UPSTREAM_NOTICES)
    record("Generated by scripts/gen-third-party-notices.ts" in upstream_text
           and "WorkNexus-DSH 发行版第三方组件声明" not in upstream_text,
           "P5 负向：上游 THIRD_PARTY_NOTICES.md 未被追加我方内容（仍归上游生成器所有）")

    # ── P6 差异集 14 补丁与条目数 ──
    patch_text = read(PATCH_14)
    paths = sorted({m.group(1) for m in re.finditer(r"^diff --git a/(.+?) b/", patch_text, re.MULTILINE)})
    record(paths == [NEW_FILE] and "new file mode" in patch_text,
           f"P6 差异集 14 = {paths}（期望 ['{NEW_FILE}']，以新增文件落盘）")
    tracked = [line.strip() for line in git("diff", "--name-only", "HEAD").splitlines() if line.strip()]
    untracked = [line.strip() for line in git("ls-files", "--others", "--exclude-standard").splitlines() if line.strip()]
    total = len({*tracked, *untracked})
    record(total == EXPECTED_DIFFSET_PATHS,
           f"P6 上游差异集条目数 = {total}（期望 {EXPECTED_DIFFSET_PATHS}）")

    # ── P7 安装态 ──
    shipped = INSTALL / "resources" / NEW_FILE
    if not INSTALL.exists():
        print("[跳过] P7 安装态检查（未检测到安装目录）")
    else:
        shipped_text = read(shipped)
        record(shipped.is_file() and all(f"`{e['name']}`" in shipped_text for e in packages),
               f"P7 安装目录随包落盘且含全部组件（{'存在' if shipped.is_file() else '缺失'}）")

    failures = [detail for ok, detail in RESULTS if not ok]
    print("-" * 60)
    print(f"结果: {len(RESULTS) - len(failures)} [OK] / {len(failures)} [FAIL]")
    for detail in failures:
        print(f"  - {detail}")
    return 1 if failures else 0


if __name__ == "__main__":
    sys.exit(main())
